"const { PrismaClient } = require('@prisma/client');
const bcrypt = require('bcrypt');

const prisma = new PrismaClient();

async function main() {
  console.log('Starting seeding database...');

  // 1. Seed Roles
  const roles = ['ADMIN', 'PRINCIPAL', 'MARKETING_CABANG'];
  const roleMap = {};

  for (const roleName of roles) {
    const role = await prisma.role.upsert({
      where: { name: roleName },
      update: {},
      create: { name: roleName },
    });
    roleMap[roleName] = role.id;
    console.log(`Role upserted: ${role.name} (ID: ${role.id})`);
  }

  // 2. Create Default Admin User
  const adminEmail = 'admin@asm.co.id';
  const adminPasswordHash = await bcrypt.hash('AdminPassword123', 10);

  const adminUser = await prisma.user.upsert({
    where: { email: adminEmail },
    update: { passwordHash: adminPasswordHash },
    create: {
      email: adminEmail,
      passwordHash: adminPasswordHash,
      roleId: roleMap['ADMIN'],
    },
  });
  console.log(`Admin user seeded: ${adminUser.email} (ID: ${adminUser.id})`);

  // 3. Create Default Marketing Cabang User (Jakarta)
  const mktEmail = 'marketing.jakarta@asm.co.id';
  const mktPasswordHash = await bcrypt.hash('MarketingPassword123', 10);

  const mktUser = await prisma.user.upsert({
    where: { email: mktEmail },
    update: { passwordHash: mktPasswordHash },
    create: {
      email: mktEmail,
      passwordHash: mktPasswordHash,
      roleId: roleMap['MARKETING_CABANG'],
      branchCode: 'JKT', // Jakarta Branch
    },
  });
  console.log(`Marketing user seeded: ${mktUser.email} (ID: ${mktUser.id}, Branch: JKT)`);

  console.log('Seeding finished successfully!');
}

main()
  .catch((e) => {
    console.error('Error during seeding:', e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
"

